## Fixed `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const config = new pulumi.Config();
const env = config.get("env") || "dev";
const region = config.get("region") || "us-east-1";
const isProd = env === "prod";

// ─── Secret: use config.requireSecret() instead of pulumi.output("literal") ───
// FIX (Defect 2): config.requireSecret() returns a pulumi.Config value that is
// already an Output<string> with secret semantics. No manual wrapping needed.
const dbPassword = config.requireSecret("dbPassword");

// ─── S3 Bucket ───
const bucket = new aws.s3.Bucket("app-bucket", {
    bucket: `myapp-assets-${env}`,
    versioning: { enabled: true },
    serverSideEncryptionConfiguration: {
        rules: [{
            applyServerSideEncryptionByDefault: {
                sseAlgorithm: "AES256",
            },
        }],
    },
    publicAccessBlock: {
        blockPublicAcls: true,
        blockPublicPolicy: true,
        blockPublicAccess: true,
        ignorePublicAcls: true,
    },
    tags: { Environment: env, Project: "myapp" },
});

// FIX (Defect 1): Use .apply() instead of an async function with await.
// pulumi.Output is NOT thenable — `await output` will not resolve correctly
// during preview and causes a crash. The correct pattern is .apply(fn).
const bucketUrl = bucket.arn.apply(
    (arn: string) => `https://s3.${region}.amazonaws.com/${arn}`
);

// ─── RDS Instance ───
const db = new aws.rds.Instance("app-db", {
    instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
    engine: "postgres",
    engineVersion: "16.1",
    allocatedStorage: 20,
    dbName: "appdb",
    username: "app-user",
    password: dbPassword,            // already an Output<string> from requireSecret
    skipFinalSnapshot: false,
    deletionProtection: isProd,      // true for prod per acceptance criteria
    backupRetentionPeriod: 14,       // >= 7 days required
    publiclyAccessible: false,
    multiAz: isProd,
    storageEncrypted: isProd,
    tags: { Environment: env, Project: "myapp" },
});

// ─── Outputs ───
// bucketUrl is now a proper pulumi.Output<string> (not a Promise)
export const bucketEndpoint = bucketUrl;
export const dbEndpoint = db.endpoint;
```

## Summary of Fixes

| # | Defect | Root Cause | Fix |
|---|--------|-----------|-----|
| 1 | `async` + `await` on `pulumi.Output` | `Output` is **not** a `Promise`; it has no `then()` that resolves during preview. Using `await` causes a synchronous crash at preview time. | Replace with `bucket.arn.apply(fn)` — the idiomatic Pulumi way to derive one `Output` from another. |
| 2 | `pulumi.output("plain-text-password")` | Wraps a **string literal** (not an `Output`) in a redundant `Output` wrapper, and stores a secret in plaintext in source. | Use `config.requireSecret("dbPassword")` which returns a properly-typed `Output<string>` with secret semantics (encrypted at rest in the Pulumi backend). |

## Why `await output` crashes

```
pulumi.Output<T>  ≠  Promise<T>
```

`Output` is a lazy, DAG-aware computation node in Pulumi's resource engine. During `pulumi preview` the engine evaluates the dependency graph **without** executing arbitrary async code. When the runtime hits `await arn`, it receives an object with no `then` method (or a non-resolving one), so the async function never settles → preview hangs or throws.

`.apply(fn)` registers a transformation *in the graph* so the engine knows how to compute the derived value at the right time.

## Required stack config

```yaml
# Pulumi.dev.yaml
config:
  myapp:env: dev
  myapp:region: us-east-1
  myapp:dbPassword:
    secure: <encrypted-value>   # set via `pulumi config set --secret myapp:dbPassword`
```

```yaml
# Pulumi.prod.yaml
config:
  myapp:env: prod
  myapp:region: us-east-1
  myapp:dbPassword:
    secure: <encrypted-value>
```

Set the secret non-interactively:

```bash
pulumi config set --secret --stack prod myapp:dbPassword "$(openssl rand -base64 32)"
```
